// Verifica se veio do PostgreSQL com dados reais
const items = $input.all();

// Verifica se tem dados REAIS (não apenas item vazio)
const hasData = items.length > 0 && Object.keys(items[0].json).length > 0;

if (!hasData) {
  return [{
    json: {
      success: true,
      hasData: false,
      rowCount: 0,
      message: "Nenhum registro encontrado na consulta",
      data: []
    }
  }];
}

// Se tem dados reais
return [{
  json: {
    success: true,
    hasData: true,
    rowCount: items.length,
    message: `${items.length} registros encontrados`,
    data: items
  }
}];

const input = $input.first().json.output;

let clean = input
  .replace(/^```sql\s*|\s*```$/gi, '') // Remove blocos ```sql
  .replace(/```/g, '')                  // Remove quaisquer ``` residuais
  .replace(/^\"|\"$/g, '')              // Remove aspas iniciais/finais
  .replace(/\n/g, ' ')                  // Substitui quebras de linha por espaços
  .replace(/\s+/g, ' ')                 // Remove espaços excessivos
  .trim(); 

return { 
  json: { 
    sql_query: clean 
  } 
};
